GitHub Issue:
Post Date: 2019-11-07T02:12:04Z
Current Date: April 4 2025
Title: No longer able to get mixined class' base class type when not including lib files
Description: **TypeScript Version:**  3.8.0-dev.20191105

**Search Terms:** mixin base type

**Code**

```ts
import * as ts from "typescript";

console.log(ts.version);

const testFilePath = "/file.ts";
const testFileText = `
type Constructor<T> = new (...args: any[]) => T;
class Base { prop!: string; }

interface Mixin {
    getResult(): number;
}

function Mixin<T extends Constructor<{}>>(Base: T): Constructor<Mixin> & T {
    return class extends Base implements Mixin {
        constructor(...args: any[]) {
            super(args);
        }

        getResult() {
            return 5;
        }
    }
}

class Child extends Mixin(Base) {
}
`;
const testSourceFile = ts.createSourceFile(testFilePath, testFileText, ts.ScriptTarget.Latest, true);
const program = getProgram();
const typeChecker = program.getTypeChecker();

const classDec = testSourceFile.statements[testSourceFile.statements.length - 1] as ts.ClassDeclaration;
const classDecType = typeChecker.getTypeAtLocation(classDec.name!);

console.log(classDecType.getBaseTypes()!.map(t => typeChecker.typeToString(t)));

console.log("---------");
console.log(ts.formatDiagnosticsWithColorAndContext(ts.getPreEmitDiagnostics(program, testSourceFile), {
    getCanonicalFileName: name => name,
    getCurrentDirectory: () => "/",
    getNewLine: () => "\n"
}));

function getProgram() {
    const options: ts.CompilerOptions = { target: ts.ScriptTarget.ES5 };
    const host: ts.CompilerHost = {
        fileExists: filePath => filePath === testFilePath,
        directoryExists: dirPath => dirPath === "/",
        getCurrentDirectory: () => "/",
        getDirectories: () => [],
        getCanonicalFileName: fileName => fileName,
        getNewLine: () => "\n",
        getDefaultLibFileName: () => "",
        getSourceFile: filePath => filePath === testFilePath ? testSourceFile : undefined,
        readFile: filePath => filePath === testFilePath ? testFileText : undefined,
        useCaseSensitiveFileNames: () => true,
        writeFile: () => {}
    };
    return ts.createProgram({
        options,
        rootNames: [testFilePath],
        host
    });
}
```

**Expected output (pre TS 3.7):**

```
3.6.3
[ 'Mixin & Base' ]
---------
error TS2318: Cannot find global type 'Array'.
error TS2318: Cannot find global type 'Boolean'.
